#include "competition_shadow.h"
#include <cmath>
namespace competition_shadow { namespace { constexpr float kPi=3.14159265358979323846f; float wrap(float x){while(x>kPi)x-=2*kPi;while(x<-kPi)x+=2*kPi;return x;} }
Controller::Controller(const Config& c):config_(c){reset();} void Controller::setConfig(const Config& c){config_=c;reset();} void Controller::reset(){mode_=ControlMode::Manual;manual_={};manualReceivedUs_=0;targetYaw_=0;headingSet_=false;waypointCount_=activeWaypoint_=0;previous_[0]=previous_[1]=previous_[2]=previous_[3]=0;physicalWriteCount_=0;} bool Controller::finite(float x)const{return std::isfinite(x);}bool Controller::fresh(bool v,uint64_t t,uint64_t n,uint32_t max)const{return v&&t&&n>=t&&n-t<=max;}
CommandResult Controller::setMode(ControlMode m,uint32_t,AuthoritativeSafety s){if(s!=AuthoritativeSafety::Disarmed)return {Ack::Rejected,1};if((uint8_t)m>3)return {Ack::Rejected,2};mode_=m;return {Ack::Accepted,0};} CommandResult Controller::setManual(const ManualCommand& c,uint64_t received){if(!finite(c.leftFront)||!finite(c.rightFront)||!finite(c.rearYaw)||!finite(c.propulsion))return{Ack::Rejected,3};if(c.leftFront<-1||c.leftFront>1||c.rightFront<-1||c.rightFront>1||c.rearYaw<-1||c.rearYaw>1||c.propulsion<0||c.propulsion>1)return{Ack::Rejected,4};manual_=c;manualReceivedUs_=received;return{Ack::Accepted,0};}CommandResult Controller::setHeading(float y,uint32_t){if(!finite(y))return{Ack::Rejected,3};targetYaw_=wrap(y);headingSet_=true;return{Ack::Accepted,0};}CommandResult Controller::setWaypoints(const Waypoint*p,uint8_t count,uint32_t,AuthoritativeSafety s){if(s!=AuthoritativeSafety::Disarmed||!p||!count||count>16)return{Ack::Rejected,5};for(uint8_t i=0;i<count;++i)if(!finite(p[i].northM)||!finite(p[i].eastM))return{Ack::Rejected,3};for(uint8_t i=0;i<count;++i)waypoints_[i]=p[i];waypointCount_=count;activeWaypoint_=0;return{Ack::Accepted,0};}
bool Controller::physicalConfigurationValid(const PhysicalConfig& c){const uint8_t a[]={c.leftChannel,c.rightChannel,c.rearChannel,c.propulsionChannel};for(uint8_t i=0;i<4;++i){if(a[i]>15)return false;for(uint8_t j=i+1;j<4;++j)if(a[i]==a[j])return false;}return c.leftMinUs<c.leftCenterUs&&c.leftCenterUs<c.leftMaxUs&&c.rightMinUs<c.rightCenterUs&&c.rightCenterUs<c.rightMaxUs&&c.rearMinUs<c.rearCenterUs&&c.rearCenterUs<c.rearMaxUs&&c.propMinUs<c.propStopUs&&c.propStopUs<c.propMaxUs&&c.calibrationComplete;}float Controller::limit(float v,float p,bool&s)const{if(v>1){v=1;s=true;}if(v<-1){v=-1;s=true;}float d=v-p;if(d>config_.slewPerStep){v=p+config_.slewPerStep;s=true;}if(d<-config_.slewPerStep){v=p-config_.slewPerStep;s=true;}return v;}void Controller::safe(Output&o,StopReason r,SafetyRequest q)const{o.leftFront=o.rightFront=o.rearYaw=o.propulsion=0;o.reason=r;o.safetyRequest=q;o.physicalGate=false;}
Output Controller::step(const SensorInput&in){Output o{};o.safety=in.safety;o.mode=mode_;o.activeWaypoint=activeWaypoint_;if(in.safety!=AuthoritativeSafety::Running){safe(o,in.safety==AuthoritativeSafety::EStop?StopReason::EStop:StopReason::None,SafetyRequest::None);return o;}if(!fresh(in.heartbeat,in.heartbeatUs,in.nowUs,config_.heartbeatStaleUs)){safe(o,StopReason::Heartbeat,SafetyRequest::Fault);return o;}if(in.vescFault){safe(o,StopReason::VescFault,SafetyRequest::Fault);return o;}bool manualMode=mode_==ControlMode::Manual,needsImu=!manualMode,needsTof=!manualMode,needsGnss=mode_==ControlMode::AutoWaypoint,needsManual=mode_!=ControlMode::AutoWaypoint;if(needsManual&&!fresh(true,manualReceivedUs_,in.nowUs,config_.manualStaleUs)){safe(o,StopReason::ManualTimeout,SafetyRequest::Disarm);return o;}if(needsImu&&(!in.imuValid||!fresh(in.imuValid,in.imuUs,in.nowUs,config_.imuStaleUs))){safe(o,in.imuValid?StopReason::ImuStale:StopReason::ImuInvalid,SafetyRequest::Fault);return o;}if(needsTof&&(!in.tofValid||!fresh(in.tofValid,in.tofUs,in.nowUs,config_.tofStaleUs))){safe(o,in.tofValid?StopReason::TofStale:StopReason::TofInvalid,SafetyRequest::Fault);return o;}if(needsGnss&&(!in.gnssValid||!fresh(in.gnssValid,in.gnssUs,in.nowUs,config_.gnssStaleUs)||!waypointCount_)){safe(o,in.gnssValid?StopReason::GnssStale:StopReason::GnssInvalid,SafetyRequest::Fault);return o;}if(manualMode){o.leftPrelimit=manual_.leftFront;o.rightPrelimit=manual_.rightFront;o.rearPrelimit=manual_.rearYaw;o.propulsionPrelimit=manual_.propulsion;}else{o.uPitch=config_.kpPitch*(config_.targetPitch-in.pitchRad)-config_.kdPitch*in.pitchRateRadS;o.uRoll=config_.kpRoll*(config_.targetRoll-in.rollRad)-config_.kdRoll*in.rollRateRadS;o.uHeight=config_.kpHeight*(config_.targetHeightM-in.tofM);float common=o.uPitch+o.uHeight;o.leftPrelimit=common+o.uRoll;o.rightPrelimit=common-o.uRoll;if(mode_==ControlMode::AutoWaypoint){const Waypoint&w=waypoints_[activeWaypoint_];float dn=w.northM-in.northM,de=w.eastM-in.eastM;o.waypointDistanceM=std::sqrt(dn*dn+de*de);o.targetYaw=std::atan2(de,dn);if(o.waypointDistanceM<=config_.waypointReachM){o.waypointReached=true;if(++activeWaypoint_>=waypointCount_){safe(o,StopReason::FinalWaypoint,SafetyRequest::Disarm);return o;}}}else if(mode_==ControlMode::HeadingHold){if(!headingSet_){targetYaw_=wrap(in.yawRad);headingSet_=true;}o.targetYaw=targetYaw_;}if(mode_==ControlMode::HeadingHold||mode_==ControlMode::AutoWaypoint){o.uYaw=config_.kpYaw*wrap(o.targetYaw-in.yawRad)-config_.kdYaw*in.yawRateRadS;o.rearPrelimit=o.uYaw;}else o.rearPrelimit=manual_.rearYaw;o.propulsionPrelimit=mode_==ControlMode::AutoWaypoint?config_.autoPropulsion:manual_.propulsion;}if(!finite(o.leftPrelimit)||!finite(o.rightPrelimit)||!finite(o.rearPrelimit)||!finite(o.propulsionPrelimit)){safe(o,StopReason::NonFinite,SafetyRequest::Fault);return o;}o.leftFront=limit(o.leftPrelimit,previous_[0],o.saturated);o.rightFront=limit(o.rightPrelimit,previous_[1],o.saturated);o.rearYaw=limit(o.rearPrelimit,previous_[2],o.saturated);o.propulsion=limit(o.propulsionPrelimit,previous_[3],o.saturated);if(o.propulsion<0)o.propulsion=0;previous_[0]=o.leftFront;previous_[1]=o.rightFront;previous_[2]=o.rearYaw;previous_[3]=o.propulsion;return o;}
const char*safetyName(AuthoritativeSafety x){switch(x){case AuthoritativeSafety::Boot:return"BOOT";case AuthoritativeSafety::Disarmed:return"DISARMED";case AuthoritativeSafety::ArmedIdle:return"ARMED_IDLE";case AuthoritativeSafety::Running:return"RUNNING";case AuthoritativeSafety::EStop:return"E_STOP";default:return"FAULT";}}const char*modeName(ControlMode x){switch(x){case ControlMode::Manual:return"MANUAL";case ControlMode::AttitudeAssist:return"ATTITUDE_ASSIST";case ControlMode::HeadingHold:return"HEADING_HOLD";default:return"AUTO_WAYPOINT";}}const char*reasonName(StopReason x){switch(x){case StopReason::None:return"NONE";case StopReason::Stop:return"STOP";case StopReason::EStop:return"E_STOP";case StopReason::Heartbeat:return"HEARTBEAT";case StopReason::ManualTimeout:return"MANUAL_TIMEOUT";case StopReason::ImuInvalid:return"IMU_INVALID";case StopReason::ImuStale:return"IMU_STALE";case StopReason::TofInvalid:return"TOF_INVALID";case StopReason::TofStale:return"TOF_STALE";case StopReason::GnssInvalid:return"GNSS_INVALID";case StopReason::GnssStale:return"GNSS_STALE";case StopReason::VescFault:return"VESC_FAULT";case StopReason::NonFinite:return"NONFINITE";default:return"FINAL_WAYPOINT";}}}